#!/usr/bin/env python3
"""Render the project front door and Artigas collaboration page without mutating existing HTML."""
from __future__ import annotations
import html, json
from pathlib import Path
from publication_index import featured_object, href, published_objects

BASE='/dc-public-realm'

def esc(x): return html.escape(str(x), quote=True)

def render_frontdoor(data_dir: Path, base: str = BASE) -> tuple[str,str]:
    overviews={o['object_entity_id']:o for o in json.loads((data_dir/'object-overviews.json').read_text(encoding='utf-8'))['object_overviews']}
    featured=featured_object(data_dir)
    featured_id=featured['entity_id']
    if featured_id != 'OBJ-0001':
        raise SystemExit(
            f"Featured object {featured_id} is not supported by the current front door: "
            "the featured research note and collaboration route are still Artigas-specific publication content"
        )
    a=overviews[featured_id]
    featured_href=href(featured_id,base,data_dir)
    artigas_href=href('OBJ-0001',base,data_dir)
    rights=esc(a['image_rights'])
    if a.get('image_license_url'):
        rights=f'<a href="{esc(a["image_license_url"])}">{rights}</a>'

    def object_card(entity):
        oid=entity['entity_id']
        return (
            f'<article class="card" data-object-id="{esc(oid)}" data-object-country="{esc(entity["country"])}">'
            f'<div class="kicker">{esc(entity["country"]).upper()}</div>'
            f'<h3><a href="{href(oid,base,data_dir)}">{esc(entity["canonical_name"])}</a></h3></article>'
        )

    object_grid=''.join(object_card(entity) for entity in published_objects(data_dir))

    home=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Diplomatic Gifts in Washington</title><link rel="stylesheet" href="{base}/assets/style.css"><style>.hero{{max-width:800px;margin:2rem 0}}.hero h1{{margin-bottom:.7rem}}.project{{border-left:4px solid #5a3d16;background:#fffdf8;padding:1rem 1.2rem;margin:2rem 0}}.project h2{{margin:.2rem 0 .8rem}}.project-object{{display:grid;grid-template-columns:minmax(220px,38%) 1fr;gap:1.4rem;align-items:start}}.project figure{{margin:0}}.project img{{display:block;width:100%;height:auto;max-height:390px;object-fit:cover}}.project figcaption{{margin-top:.4rem;font-family:ui-sans-serif,system-ui,sans-serif;color:#666;font-size:.7rem;line-height:1.4}}.object-meta{{font-family:ui-sans-serif,system-ui,sans-serif;color:#666;font-size:.86rem;margin:.2rem 0 .8rem}}.object-intro{{font-size:1.05rem;line-height:1.55}}.research-note{{margin:1.2rem 0 0;padding-top:1rem;border-top:1px solid #ddd}}.research-note h3{{font-family:ui-sans-serif,system-ui,sans-serif;font-size:.9rem;text-transform:uppercase;letter-spacing:.05em;margin:0 0 .4rem}}.actions{{margin:1.2rem 0}}.actions .button{{margin-bottom:.5rem}}@media(max-width:600px){{.project-object{{grid-template-columns:1fr}}.project img{{max-height:none}}}}</style></head><body><header><div class="kicker">Diplomatic Gifts in Washington · public art research</div><nav><a href="{base}/">Explore</a><a href="{base}/collaborate/">Research missions</a><a href="{base}/methodology/">About the research</a><a href="{base}/data/">Data</a></nav></header><main><section class="hero"><div class="kicker">PUBLIC ART · DIPLOMATIC HISTORY</div><h1>Diplomatic Gifts in Washington</h1><p class="lede">This project documents diplomatic monuments in Washington, D.C., and invites the public to help research their histories.</p><p>Government files, newspapers, photographs, archival collections, and museum records can clarify who made these works, how they came to Washington, and how their histories have been recorded.</p></section><section class="project"><div class="kicker">CURRENT PROJECT · {esc(featured['country']).upper()}</div><div class="project-object"><figure><img src="{esc(a['image_url'])}" alt="{esc(a['image_alt'])}"><figcaption>{esc(a['image_credit'])} · {rights} · <a href="{esc(a['image_source_url'])}">Image record</a></figcaption></figure><div><h2>{esc(featured['canonical_name'])}</h2><p class="object-meta">{esc(a['location'])} · {esc(a['event_label'])} {esc(a['event_date'])}</p><p class="object-intro"><strong>{esc(a['subject_name'])}</strong> ({esc(a['subject_dates'])}). {esc(a['subject_bio'])} <a href="{esc(a['subject_source_url'])}">Source</a></p><div class="actions"><a class="button" href="{featured_href}">View the memorial</a></div><aside class="research-note"><h3>Research in progress</h3><p>Published records differ on the predecessor monument and parts of the fabrication history. The detailed record shows the sources, disagreements, and open questions.</p><p><a href="{base}/collaborate/artigas/">Help research the Artigas memorial</a></p></aside></div></div></section><section><h2>Take part in the research</h2><p>You do not need to be an art historian to contribute. Research missions identify a specific question, records that may answer it, and the information needed to document a finding.</p><p>A contribution may confirm an existing statement, qualify it, identify a conflicting account, or leave the question unresolved. Sources are reviewed before the public record changes.</p><p><a class="button" href="{base}/collaborate/">Browse research missions</a></p></section><section><h2>Explore the records</h2><div class="grid">{object_grid}</div></section><section><h2>How the research works</h2><p>Object pages present the current catalog record. Each historical or attribution statement is linked to its sources. When reliable records disagree, the disagreement remains visible.</p><p>The <a href="{base}/methodology/">research methodology</a> explains how sources are reviewed and how records are updated.</p></section></main><footer>Research is ongoing. Records may change when additional sources are reviewed.</footer></body></html>'''

    collab=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Artigas Research Missions</title><link rel="stylesheet" href="{base}/assets/style.css"><style>.mission{{border-left:4px solid #7a3e00;background:#fffdf8;padding:1rem 1.2rem;margin:1.2rem 0}}.mission h3{{margin-top:.2rem}}.small{{font-family:ui-sans-serif,system-ui,sans-serif;color:#666;font-size:.9rem}}.steps{{counter-reset:step;list-style:none;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:1rem}}.steps li{{border-top:3px solid #ddd;padding-top:.6rem}}.steps li:before{{counter-increment:step;content:counter(step);font-family:ui-sans-serif,system-ui,sans-serif;font-weight:700;margin-right:.5rem}}</style></head><body><header><div class="kicker">Diplomatic Gifts in Washington · public research</div><nav><a href="{base}/">Explore</a><a href="{base}/collaborate/">Research missions</a><a href="{artigas_href}">Artigas record</a><a href="{base}/methodology/">About the research</a></nav></header><main><div class="kicker">JOSÉ GERVASIO ARTIGAS MEMORIAL</div><h1>Help Research the Artigas Memorial</h1><p class="lede">Historical records leave several questions about the Washington monument unresolved. You can help locate the records needed to answer them.</p><p>Choose a mission below. Each mission defines the question and the material being sought. No specialized training is required; accurate citations and complete records are more useful than interpretation.</p><h2>Research missions</h2><article class="mission"><div class="kicker">MISSION 1 · NEWSPAPER RESEARCH</div><h3>Find the 1949 <em>El Día</em> account</h3><p>Locate the complete article “Monumento a Artigas en Washington.” It may contain contemporary information about production, financing, shipment, or installation.</p><p><strong>Useful contribution:</strong> complete article pages, continuation pages, captions, credits, publication date, and page numbers.</p><a class="button" href="{base}/tasks/ury-art-002/">Mission details</a></article><article class="mission"><div class="kicker">MISSION 2 · ARCHIVAL RESEARCH</div><h3>Find the original commission records</h3><p>Uruguay's heritage documentation refers to an 1894 commission and an 1896 contract concerning Juan Luis Blanes, Juan Manuel Blanes, and Dante Costa. Locate the underlying records.</p><p><strong>Useful contribution:</strong> archival citation, catalog record, image, transcription, or authoritative reproduction.</p><a class="button" href="{base}/tasks/ury-art-003/">Mission details</a></article><article class="mission"><div class="kicker">MISSION 3 · DIPLOMATIC HISTORY</div><h3>Trace the Washington monument, 1947–1951</h3><p>Locate correspondence or administrative records concerning authorization, fabrication, shipment, dedication, or installation of the Washington bronze.</p><p><strong>Useful contribution:</strong> folder citation, scan, finding-aid reference, or repository contact that identifies relevant records.</p><a class="button" href="{base}/tasks/ury-art-001/">Mission details</a></article><article class="mission"><div class="kicker">MISSION 4 · MUSEUM RECORDS</div><h3>Trace the Smithsonian inventory's sources</h3><p>The Smithsonian inventory cites earlier research without assigning each source to individual statements. Help locate those materials so their contribution to the catalog record can be documented.</p><p><a href="https://github.com/danielastone/dc-public-realm/issues/19">Goode (1974)</a> · <a href="https://github.com/danielastone/dc-public-realm/issues/20">Michael Richman research</a> · <a href="https://github.com/danielastone/dc-public-realm/issues/21">NPS record (1985)</a> · <a href="https://github.com/danielastone/dc-public-realm/issues/22">Smithsonian research project (1991)</a></p></article><h2>What happens to your contribution</h2><ol class="steps"><li><strong>You submit a source.</strong><br><span class="small">Provide enough information for another researcher to locate the same record.</span></li><li><strong>The source is reviewed.</strong><br><span class="small">The project checks identity, date, relevance, and whether the statement derives from another source.</span></li><li><strong>The evidence is recorded.</strong><br><span class="small">Accepted material is linked to the specific historical or attribution statement it bears on.</span></li><li><strong>The public record is updated.</strong><br><span class="small">The source may confirm, qualify, contradict, or leave the statement unresolved.</span></li></ol><h2>Ways to contribute</h2><p>Useful contributions include archival citations, finding-aid references, newspaper pages, photographs of inscriptions, catalog records, scans where reproduction is permitted, translations, and corrections supported by a source.</p><p>If an archive does not permit public posting of a scan, submit the citation and repository information instead.</p><h2>Research standards</h2><p>A contribution does not become part of the catalog record automatically. Sources are reviewed first. When reliable records disagree, both remain documented until additional evidence resolves the difference.</p><p><a class="button" href="{artigas_href}">Explore the Artigas record</a><a class="button" href="{base}/methodology/">Research methodology</a></p></main><footer>Public contributions support the research record. Submitted material is reviewed before publication.</footer></body></html>'''
    return home, collab
